mapper.select:
SELECT to_char(created_at, 'YYYY-MM-DD') AS d, COUNT(*) AS c FROM user_feedback WHERE deleted = 0 AND created_at >= #{start}
AND user_id IN (SELECT id FROM sys_user WHERE deleted = 0 AND created_by = #{createdBy})
GROUP BY to_char(created_at, 'YYYY-MM-DD') ORDER BY d

SELECT id, user_id, session_id, message_id, is_liked, intent_type, deleted, created_at, updated_at FROM user_feedback WHERE deleted = 0
AND intent_type = #{intentType}
AND user_id IN (SELECT id FROM sys_user WHERE deleted = 0 AND created_by = #{createdBy}) ORDER BY created_at DESC
